// SPEC-056 fixture-intent coverage (AC-34..38). The spec's shared
// fixtures/manifest.json (SPEC-004) is not present in this repo, and a fixture
// generated by this app's own writer would prove no more than the round-trip
// tests already do (it is not a genuine Word/LibreOffice file). So instead of a
// binary fixture this pins the same guarantees against a model holding one
// equation of every construct in the closed set: each renders (AC-34), and the
// inline (AC-35), display (AC-36), numbered (AC-37) and unsupported (AC-38)
// cases are exercised, round-tripping through both formats.
import { describe, expect, it } from "vitest";
import { layoutRow } from "./render";
import { parseLinear } from "./linearParse";
import { serializeOmmlEquation, parseOmmlEquation } from "../docx/omml";
import { MATH_NAMESPACE } from "../docx/xml";
import { serializeMathML, parseMathML } from "./mathml";
import { parseXml } from "../core/xml";
import { firstStructuralDifference } from "../equality";
import { insertNumberedDisplayEquation } from "../commands.equations";
import { createDocument, type EquationSpec, type MathNode, type Paragraph } from "../documentModel";

// One equation of every construct in the set (AC-34).
const ONE_OF_EVERY: Record<string, MathNode> = {
  sym: { kind: "sym", text: "x", variant: "italic" },
  frac: parseLinear("\\frac{a}{b}")[0],
  script: parseLinear("x_i^2")[0],
  radical: parseLinear("\\sqrt[3]{x}")[0],
  nary: parseLinear("\\sum_{i=1}^{n} i")[0],
  delim: parseLinear("\\left( a \\right)")[0],
  matrix: parseLinear("\\matrix{a & b \\\\ c & d}")[0],
  accent: parseLinear("\\hat{x}")[0],
  func: parseLinear("\\sin")[0],
  text: parseLinear("\\text{if }")[0],
};

function domOf(xml: string): Element {
  return parseXml(xml).documentElement;
}

/** The OMML string carries `m:` prefixes but no namespace declaration on its
 * own; wrap it so it parses, then hand the oMath element to the parser. */
function ommlDom(xml: string): Element {
  const wrapped = parseXml(`<m:wrap xmlns:m="${MATH_NAMESPACE}">${xml}</m:wrap>`);
  return wrapped.documentElement.firstElementChild as Element;
}

describe("one equation of every construct (AC-34)", () => {
  for (const [kind, node] of Object.entries(ONE_OF_EVERY)) {
    it(`renders and round-trips a ${kind}`, () => {
      expect(node.kind === kind || (kind === "sym" && node.kind === "sym")).toBe(true);
      // Renders (AC-34): the layout engine produces a box, never throwing.
      expect(layoutRow([node])).toBeTruthy();
      const eq: EquationSpec = { display: "inline", body: [node] };
      // .docx OMML round-trip.
      const omml = parseOmmlEquation(ommlDom(serializeOmmlEquation(eq)));
      expect(firstStructuralDifference(eq.body, omml.body)).toBeNull();
      // .odt MathML round-trip.
      const mathml = parseMathML(domOf(serializeMathML(eq)));
      expect(firstStructuralDifference(eq.body, mathml.body)).toBeNull();
    });
  }
});

describe("inline / display / numbered / unsupported (AC-35..38)", () => {
  it("renders an inline equation (AC-35)", () => {
    const eq: EquationSpec = { display: "inline", body: parseLinear("a + b") };
    expect(layoutRow(eq.body)).toBeTruthy();
    expect(eq.display).toBe("inline");
  });

  it("renders a display equation (AC-36)", () => {
    const eq: EquationSpec = { display: "block", body: parseLinear("x = \\frac{-b}{2a}") };
    expect(layoutRow(eq.body)).toBeTruthy();
    const mathml = parseMathML(domOf(serializeMathML(eq)));
    expect(mathml.display).toBe("block");
  });

  it("renders a numbered display equation (AC-37)", () => {
    const model = createDocument("d");
    (model.sections[0].blocks[0] as Paragraph).runs = [];
    const caret = { anchor: { section: 0, block: 0, offset: 0 }, focus: { section: 0, block: 0, offset: 0 } };
    const { model: out, selection } = insertNumberedDisplayEquation(model, caret, parseLinear("E = mc^2"));
    const para = out.sections[0].blocks[selection.focus.block] as Paragraph;
    expect(para.runs[0].equation?.display).toBe("block");
    expect(para.runs.some((r) => r.field?.kind === "unsupported" && r.field.code.startsWith("SEQ Equation"))).toBe(true);
    expect(para.bookmarks?.length).toBe(1);
  });

  it("renders an unsupported construct as the read-only box (AC-38)", () => {
    const opaque: MathNode = { kind: "opaqueMath", source: "<mglyph/>", linear: "?" };
    const box = layoutRow([opaque]);
    // The layout carries the opaque node's linear form for the read-only box.
    expect(JSON.stringify(box)).toContain("opaque");
  });
});
